import { z } from 'zod'
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { prisma } from '../prisma.js'
import { requireWriteAccess } from '../auth.js'
import { toolJson, withToolErrors } from '../errors.js'
import { QUEUE_TERMINAL_STATUSES } from '@shared/queue-identity.js'

// M32 spec 4.4 — same semantics as s4m-queue's archiveSubtree/unarchiveSubtree:
// recursive reply subtree locked with FOR UPDATE inside one serializable
// transaction, terminal check (archive only), per-row idempotency via the
// archived_at filter in the UPDATE's WHERE clause. No NOTIFY: archiving doesn't
// change status or ownership.
const inputSchema = z.object({
  message_id: z.string().uuid(),
})

interface SubtreeRow {
  id: string
  status: string
}

type TransactionClient = {
  $queryRaw: (strings: TemplateStringsArray, ...values: unknown[]) => Promise<SubtreeRow[]>
  agentMessage: {
    updateMany: (args: { where: Record<string, unknown>; data: Record<string, unknown> }) => Promise<{ count: number }>
  }
}

async function lockSubtree(tx: TransactionClient, messageId: string): Promise<SubtreeRow[]> {
  return tx.$queryRaw`
    WITH RECURSIVE subtree AS (
      SELECT id, status FROM agent_message
       WHERE id = ${messageId}::uuid
      UNION ALL
      SELECT m.id, m.status FROM agent_message m
       JOIN subtree ON m.in_reply_to = subtree.id
    )
    SELECT subtree.id, subtree.status FROM subtree
     FOR UPDATE
  `
}
```

