Handler:

```ts
async function archiveSubtree(messageId: string) {
  return prisma.$transaction(async (tx) => {
    const rows = await lockSubtree(tx, messageId)
    if (rows.length === 0) {
      throw new Error(`QUEUE_NOT_FOUND: message ${messageId} does not exist`)
    }
    const blocked = rows.find((row) => (QUEUE_TERMINAL_STATUSES as readonly string[]).includes(row.status))
    if (blocked) {
      throw new Error(`QUEUE_NOT_TERMINAL: message ${blocked.id} has terminal status '${blocked.status}' — its subtree cannot be archived`)
    }
    const ids = rows.map((row) => row.id)
    const stamp = new Date()
    const result = await tx.agentMessage.updateMany({
      where: { id: { in: ids }, archived_at: null },
      data: { archived_at: stamp },
    })
    return { message_id: messageId, total: rows.length, archived: result.count }
  })
}

async function unarchiveSubtree(messageId: string) {
  return prisma.$transaction(async (tx) => {
    const rows = await lockSubtree(tx, messageId)
    if (rows.length === 0) {
      throw new Error(`QUEUE_NOT_FOUND: message ${messageId} does not exist`)
    }
    const ids = rows.map((row) => row.id)
    const result = await tx.agentMessage.updateMany({
      where: { id: { in: ids }, archived_at: { not: null } },
      data: { archived_at: null },
    })
    return { message_id: messageId, total: rows.length, unarchived: result.count }
  })
}

export function registerQueueArchiveTools(server: McpServer) {
  server.registerTool('queue_archive', {
    title: 'Queue archive',
    description:
      'Archive a message together with its complete reply subtree (recursive walk over in_reply_to, locked with FOR UPDATE in one transaction). Sets archived_at on every as-yet-unarchived row; idempotent per row. Fails with QUEUE_NOT_FOUND for an unknown message and QUEUE_NOT_TERMINAL when the subtree contains a finished (done/failed/cancelled) row. Use for queue cleanup — including by the cleanup job.',
    inputSchema,
    annotations: { readOnlyHint: false, idempotentHint: true },
  }, async ({ message_id }) => withToolErrors(() => {
    await requireWriteAccess()
    return toolJson(await archiveSubtree(message_id))
  }))
  server.registerTool('queue_unarchive', {
    title: 'Queue unarchive',
    description:
      'Restore an archived message together with its complete reply subtree by resetting archived_at to null, row by row; idempotent per row. No terminal check: unarchiving is always allowed. Fails with QUEUE_NOT_FOUND for an unknown message.',
    inputSchema,
    annotations: { readOnlyHint: false, idempotentHint: true },
  }, async ({ message_id }) => withToolErrors(() => {
    await requireWriteAccess()
    return toolJson(await unarchiveSubtree(message_id))
  }))
}
```

